-- AlterTable
ALTER TABLE "formations" ADD COLUMN "slug" TEXT;

-- CreateIndex
CREATE UNIQUE INDEX "formations_slug_key" ON "formations"("slug");

-- Liaison des formations existantes à leur fiche pédagogique (frontend/data/formations)
UPDATE "formations" SET "slug" = 'prise-de-parole-en-public' WHERE "title" = 'Prise de parole en public' AND "slug" IS NULL
  AND NOT EXISTS (SELECT 1 FROM "formations" f2 WHERE f2."slug" = 'prise-de-parole-en-public');
