SELECT 'formation-cv-entretien-embauche', 'cv-entretien-embauche', 'CV, lettre et entretien d''embauche', 'Un CV qui passe le tri en 30 secondes, une lettre qui donne envie, un entretien préparé avec la méthode STAR.', 'Insertion professionnelle', '📄', 'images/orientation.webp', '3 semaines · 18 h', 'Dakar & En ligne', 'Construire un CV clair d''une page, adapté à chaque offre ; Transformer tes expériences (stages, associations, petits boulots) en résultats concrets ; Rédiger une lettre de motivation courte et personnalisée ; Optimiser ton profil LinkedIn', 'Avoir un projet de candidature (stage, emploi, alternance, bourse) même approximatif.', 'Étudiants en recherche de stage, jeunes diplômés, personnes en reconversion.', '[{"module": "Le CV qui passe le tri", "lessons": ["La structure", "Des résultats, pas des tâches", "Adapter à chaque offre"], "duration": "Semaine 1"}, {"module": "Lettre de motivation et présence en ligne", "lessons": ["La lettre en 3 paragraphes", "Ton profil LinkedIn"], "duration": "Semaine 1"}, {"module": "Préparer l''entretien", "lessons": ["Se renseigner", "Les questions classiques", "La méthode STAR"], "duration": "Semaine 2"}, {"module": "Le jour J et après", "lessons": ["Présentation et attitude", "Tes questions au recruteur", "Le suivi"], "duration": "Semaine 3"}]'::jsonb, 'Attestation WOW de préparation à l''emploi, délivrée après la simulation d''entretien filmée et la remise d''un dossier de candidature complet.', 'PUBLISHED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM "formations" WHERE "slug" = 'cv-entretien-embauche' OR "title" = 'CV, lettre et entretien d''embauche');
