SELECT 'formation-finance-personnelle', 'finance-personnelle', 'Finance personnelle & budget', 'Tenir un budget, épargner même avec peu, utiliser le mobile money en sécurité et éviter les pièges du crédit.', 'Compétences de vie', '💰', 'images/citoyennete.webp', '3 semaines · 15 h', 'Dakar & En ligne', 'Suivre tes revenus et dépenses et savoir où va ton argent ; Construire un budget mensuel réaliste ; Constituer une épargne de précaution, même petite ; Comparer les solutions : compte bancaire, mobile money, tontine, mutuelle d''épargne', 'Aucun. Un téléphone et la volonté de noter ses dépenses pendant un mois.', 'Étudiants boursiers, jeunes salariés, entrepreneurs débutants et toute personne qui veut reprendre le contrôle de son argent.', '[{"module": "Savoir où va son argent", "lessons": ["Noter toutes ses dépenses", "Besoins, envies, obligations"], "duration": "Semaine 1"}, {"module": "Budget et épargne", "lessons": ["Le budget mensuel", "Se payer en premier", "Le fonds d''urgence"], "duration": "Semaine 1-2"}, {"module": "Outils financiers et crédit", "lessons": ["Banque, mobile money, tontine, microfinance", "Le vrai coût du crédit"], "duration": "Semaine 2"}, {"module": "Sécurité et objectifs", "lessons": ["Les arnaques au mobile money", "Objectifs financiers"], "duration": "Semaine 3"}]'::jsonb, 'Attestation WOW d''éducation financière, délivrée après la remise du plan financier sur 12 mois.', 'PUBLISHED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM "formations" WHERE "slug" = 'finance-personnelle' OR "title" = 'Finance personnelle & budget');
