SELECT 'formation-gestion-de-projet', 'gestion-de-projet', 'Gestion de projet', 'Cadrer, planifier, piloter et livrer un projet à l''heure, avec des méthodes classiques et agiles.', 'Management & Direction', '🗂️', 'images/formations_hero.webp', '4 semaines · 28 h', 'Dakar & En ligne', 'Cadrer un projet : objectif, périmètre, livrables, parties prenantes ; Découper le travail en tâches (organigramme des tâches) et estimer leur durée ; Construire un planning et repérer le chemin critique ; Établir un budget prévisionnel et le suivre', 'Avoir un projet à mener (événement, mémoire, lancement de produit, action associative) ou en choisir un pendant la formation.', 'Étudiants, responsables associatifs, organisateurs d''événements, jeunes salariés et porteurs de projets.', '[{"module": "Cadrer le projet", "lessons": ["La note de cadrage", "Les parties prenantes"], "duration": "Semaine 1"}, {"module": "Planifier", "lessons": ["Découper le travail", "Le planning et le chemin critique", "Le budget"], "duration": "Semaine 2"}, {"module": "Risques et pilotage", "lessons": ["Gérer les risques", "Suivre l''avancement"], "duration": "Semaine 3"}, {"module": "L''agilité et la clôture", "lessons": ["Kanban", "Scrum en bref", "Clôturer"], "duration": "Semaine 4"}]'::jsonb, 'Attestation WOW de gestion de projet, délivrée après la présentation du dossier de projet (cadrage, planning, risques, sprint et rétrospective).', 'PUBLISHED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM "formations" WHERE "slug" = 'gestion-de-projet' OR "title" = 'Gestion de projet');
