SELECT 'formation-negociation-gestion-conflits', 'negociation-gestion-conflits', 'Négociation & gestion des conflits', 'Obtenir un accord juste sans abîmer la relation, et transformer les tensions en solutions.', 'Soft Skills & Communication', '⚖️', 'images/about_team.webp', '3 semaines · 18 h', 'Dakar & En ligne', 'Préparer une négociation : objectifs, limites, alternative de repli ; Distinguer les positions (ce que l''on demande) des intérêts (pourquoi on le demande) ; Proposer plusieurs options et s''appuyer sur des critères objectifs ; Négocier un stage, une rémunération ou un délai', 'Avoir suivi « Communication efficace » est un plus, pas une obligation.', 'Étudiants, responsables associatifs, commerciaux, entrepreneurs, jeunes salariés qui négocient un stage, un salaire ou un contrat.', '[{"module": "Préparer une négociation", "lessons": ["Positions et intérêts", "Ta meilleure alternative (MESORE / BATNA)", "Objectif, point de départ et limite"], "duration": "Semaine 1"}, {"module": "Négocier", "lessons": ["Inventer des options", "Les critères objectifs", "Négocier un stage ou un salaire"], "duration": "Semaine 2"}, {"module": "Gérer les conflits", "lessons": ["Les 5 modes face au conflit", "Faire baisser la tension", "La médiation entre pairs"], "duration": "Semaine 3"}]'::jsonb, 'Attestation WOW de négociation et de gestion des conflits, délivrée après le jeu de rôle filmé et la médiation simulée.', 'PUBLISHED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM "formations" WHERE "slug" = 'negociation-gestion-conflits' OR "title" = 'Négociation & gestion des conflits');
