SELECT 'formation-numerique-ia-au-travail', 'numerique-ia-au-travail', 'Outils numériques & IA au travail', 'Bureautique efficace, IA générative utilisée avec méthode et esprit critique, et bonnes pratiques de cybersécurité.', 'Numérique & Intelligence artificielle', '🤖', 'images/innovation.webp', '4 semaines · 24 h', 'Dakar & En ligne', 'Organiser tes fichiers et travailler dans le cloud (Google Drive, OneDrive) ; Produire des documents, tableaux et présentations professionnels ; Rédiger des consignes efficaces (prompts) pour un assistant d''IA ; Vérifier les réponses d''une IA et repérer les erreurs et inventions', 'Savoir utiliser un smartphone. Un accès à un ordinateur est recommandé (salle du club ou cybercafé).', 'Étudiants, jeunes professionnels, entrepreneurs et associations qui veulent gagner du temps avec le numérique.', '[{"module": "Les fondamentaux du travail numérique", "lessons": ["Organiser ses fichiers", "Traitement de texte et présentations", "Le tableur"], "duration": "Semaine 1"}, {"module": "L''IA générative avec méthode", "lessons": ["Comment fonctionne une IA générative", "Écrire une bonne consigne", "Usages utiles"], "duration": "Semaine 2"}, {"module": "Esprit critique et éthique", "lessons": ["Vérifier", "Transparence et plagiat", "Données personnelles et confidentialité"], "duration": "Semaine 3"}, {"module": "Cybersécurité au quotidien", "lessons": ["Mots de passe et double authentification", "Hameçonnage et arnaques", "Mises à jour et sauvegardes"], "duration": "Semaine 4"}]'::jsonb, 'Attestation WOW de compétences numériques, délivrée après les exercices pratiques et la check-list de sécurité.', 'PUBLISHED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM "formations" WHERE "slug" = 'numerique-ia-au-travail' OR "title" = 'Outils numériques & IA au travail');
